}

@Injectable() export class InvoiceService { /* бизнес-логика + персистентность; может использовать PdfService */ }
@Injectable() export class PdfService { /* рендерит PDF; внутренний для биллинга */ }

@Module({
  controllers: [InvoicesController],
  providers: [InvoiceService, PdfService],
  exports: [InvoiceService], // PdfService остаётся приватным
})
export class BillingModule {}

@Module({
  imports: [BillingModule], // даёт доступ только к экспортированному InvoiceService
  providers: [NotificationsService],
})
export class NotificationsModule {}

Controller — тонкий HTTP-адаптер; оба сервиса держат логику; граница экспортирует только InvoiceService, чтобы NotificationsModule мог его инжектить, а PdfService остаётся инкапсулированным внутри биллинга.

